/* Every member waveform is drawn. Runs only in the visitor's browser. */
'use strict';
importScripts('pca-core.js?v=1');
let source=null,loadGeneration=0,pcaResult=null;const jobs=new Map(),cache=new Map(),memberCache=new Map();
function vector(row){const size=row.dtype==='<f8'?8:4,n=row.length,buffer=new ArrayBuffer(n*size),bytes=new Uint8Array(buffer),data=row.data,chunk=4*262144;let offset=0;for(let i=0;i<data.length;i+=chunk){const decoded=atob(data.slice(i,i+chunk));for(let j=0;j<decoded.length;j++)bytes[offset++]=decoded.charCodeAt(j);}if(offset!==bytes.length)throw Error('Waveform byte count mismatch');return row.dtype==='<f8'?new Float64Array(buffer):row.dtype==='<f4'?new Float32Array(buffer):new Int32Array(buffer);}
async function load(data){const generation=++loadGeneration;jobs.clear();cache.clear();memberCache.clear();source=null;pcaResult=null;const n=data.n_samples;let waves,index,originalRows=null,full=!!data.arrays.waveforms;
 if(full){waves=vector(data.arrays.waveforms);const digest=[...new Uint8Array(await crypto.subtle.digest('SHA-256',waves.buffer))].map(v=>v.toString(16).padStart(2,'0')).join('');if(digest!==data.arrays.waveforms.sha256)throw Error('Full waveform integrity check failed');index=vector(data.arrays.atom_index);}
 else{const samples=[];const ids=[],rows=[];data.atoms.forEach((a,i)=>a.traces.forEach(t=>{samples.push(...t.waveform);ids.push(i);rows.push(t.row);}));waves=Float64Array.from(samples);index=Int32Array.from(ids);originalRows=Int32Array.from(rows);}
 const amplitudes=new Float64Array(index.length),bounds=data.atoms.map(()=>[Infinity,-Infinity]);for(let r=0;r<index.length;r++){const b=bounds[index[r]];let lo=Infinity,hi=-Infinity;for(let j=0;j<n;j++){const v=waves[r*n+j];if(!Number.isFinite(v))throw Error('Nonfinite waveform value');if(v<b[0])b[0]=v;if(v>b[1])b[1]=v;if(v<lo)lo=v;if(v>hi)hi=v;}amplitudes[r]=hi-lo;}
 if(generation!==loadGeneration)return;source={waves,index,bounds,n,full,amplitudes,originalRows,times:data.times,initialLabels:data.atoms.map(a=>a.initial_cluster)};postMessage({type:'ready',full,rows:index.length});
}
function clusterAt(job,row){return job.row_labels?.[source.originalRows?source.originalRows[row]:row]?.cluster??job.labels[source.index[row]];}
function draw(job){if(!source)return;const {id,width:w,height:h,labels,groups,axisGroups=groups,mini,zoom=1,opacity=null,coverage='all'}=job,key=JSON.stringify([w,h,labels,job.row_labels,groups,axisGroups,mini,zoom,opacity,coverage]),stored=cache.get(key);if(stored){createImageBitmap(stored.canvas).then(bitmap=>postMessage({type:'image',id,bitmap,done:true,drawn:stored.drawn,low:stored.low,high:stored.high,full:source.full,sampled:stored.sampled,total:stored.total},[bitmap]));return;}
 const canvas=new OffscreenCanvas(w,h),ctx=canvas.getContext('2d'),wanted=new Map(axisGroups.map(g=>[g.id,g.color]));let low=Infinity,high=-Infinity,total=0;
 source.bounds.forEach((b,i)=>{if(wanted.has(labels[i])){low=Math.min(low,b[0]);high=Math.max(high,b[1]);}});if(Object.keys(job.row_labels||{}).length)for(let row=0;row<source.index.length;row++)if(wanted.has(clusterAt(job,row))){const b=source.bounds[source.index[row]];low=Math.min(low,b[0]);high=Math.max(high,b[1]);}const visible=new Set(groups.map(g=>g.id));for(let row=0;row<source.index.length;row++)if(visible.has(clusterAt(job,row)))total++;
 if(!Number.isFinite(low)){low=-1;high=1;}const centered=low<=0&&high>=0,mid=centered?0:(low+high)/2,span=Math.max((centered?2*Math.max(Math.abs(low),Math.abs(high)):high-low)*1.12,1e-9)/zoom;low=mid-span/2;high=mid+span/2;
 const l=mini?7:65,t=mini?7:26,r=mini?7:15,b=mini?7:42,pw=w-l-r,ph=h-t-b;ctx.fillStyle='#fff';ctx.fillRect(0,0,w,h);ctx.strokeStyle='#dce5ec';ctx.lineWidth=1;ctx.font='13px system-ui';ctx.fillStyle='#38546a';
 if(!mini){for(let k=0;k<5;k++){const y=t+ph*k/4;ctx.beginPath();ctx.moveTo(l,y);ctx.lineTo(w-r,y);ctx.stroke();ctx.textAlign='right';ctx.fillText(Number(high-span*k/4).toPrecision(3),l-8,y+4);}ctx.textAlign='center';for(let k=0;k<5;k++)ctx.fillText(Number((job.duration*k/4).toPrecision(3)).toString(),l+pw*k/4,h-24);ctx.fillText('Time (ms)',l+pw/2,h-6);ctx.textAlign='left';ctx.fillText('Amplitude (source units)',l,16);}
 const sampled=coverage==='sample24',selectedRows=new Set();
 if(sampled){for(const group of groups){const rows=[];for(let i=0;i<source.index.length;i++)if(clusterAt(job,i)===group.id)rows.push(i);rows.sort((a,b)=>source.times[a]-source.times[b]||a-b);const n=Math.min(24,rows.length);for(let i=0;i<n;i++)selectedRows.add(rows[n===1?0:Math.floor(i*(rows.length-1)/(n-1))]);}}
 const counts=new Map(groups.map(g=>[g.id,0]));for(let row=0;row<source.index.length;row++){const cid=clusterAt(job,row);if(counts.has(cid))counts.set(cid,counts.get(cid)+1);}const layers=[...groups].sort((a,b)=>counts.get(b.id)-counts.get(a.id));
 let row=0,layer=0,drawn=0,lastImage=performance.now();const token={cancel:false};jobs.set(id,token);ctx.save();ctx.beginPath();ctx.rect(l,t,pw,ph);ctx.clip();ctx.lineWidth=mini?.5:.7;
 async function step(){if(token.cancel||jobs.get(id)!==token)return;let visited=0,hits=0;const group=layers[layer],path=new Path2D();while(row<source.index.length&&hits<800&&visited<50000){const cid=clusterAt(job,row);if(cid===group.id&&(!sampled||selectedRows.has(row))){const start=row*source.n;path.moveTo(l,t+(high-source.waves[start])/span*ph);for(let j=1;j<source.n;j++)path.lineTo(l+j/(source.n-1)*pw,t+(high-source.waves[start+j])/span*ph);hits++;drawn++;}row++;visited++;}ctx.globalAlpha=(sampled?.75:Number.isFinite(opacity)?Math.max(.02,Math.min(1,opacity)):Math.max(.015,Math.min(.5,3/Math.sqrt(Math.max(1,counts.get(group.id))))))*(group.opacity??1);ctx.strokeStyle=group.color;ctx.stroke(path);
  if(row>=source.index.length){layer++;row=0;}const done=layer>=layers.length;if(done||performance.now()-lastImage>180){lastImage=performance.now();const bitmap=await createImageBitmap(canvas);if(token.cancel){bitmap.close();return;}postMessage({type:'image',id,bitmap,done,drawn,total,low,high,full:source.full,sampled},[bitmap]);}
  if(!done)setTimeout(step,0);else{ctx.restore();jobs.delete(id);cache.set(key,{canvas,drawn,low,high,sampled,total});while(cache.size>32)cache.delete(cache.keys().next().value);}
 }
 step().catch(e=>postMessage({type:'error',id,error:e.message}));
}
function members(job){
 if(!source)throw Error('Waveforms are not ready');const {id,labels,cluster,axisGroups,order='row'}=job,pageSize=Math.max(1,Math.min(96,Math.floor(job.pageSize)||24)),key=JSON.stringify([labels,cluster,order]);let rows=memberCache.get(key);
 if(!rows){rows=[];for(let i=0;i<source.index.length;i++)if(labels[source.index[i]]===cluster)rows.push(i);if(order==='amplitude')rows.sort((a,b)=>source.amplitudes[b]-source.amplitudes[a]||a-b);memberCache.set(key,rows);while(memberCache.size>8)memberCache.delete(memberCache.keys().next().value);}
 const total=rows.length,pages=Math.max(1,Math.ceil(total/pageSize)),page=Math.max(1,Math.min(pages,Math.floor(job.page)||1)),start=(page-1)*pageSize,wanted=new Set(axisGroups.map(g=>g.id));let low=Infinity,high=-Infinity;
 source.bounds.forEach((b,i)=>{if(wanted.has(labels[i])){low=Math.min(low,b[0]);high=Math.max(high,b[1]);}});if(Object.keys(job.row_labels||{}).length)for(let row=0;row<source.index.length;row++)if(wanted.has(clusterAt(job,row))){const b=source.bounds[source.index[row]];low=Math.min(low,b[0]);high=Math.max(high,b[1]);}if(!Number.isFinite(low)){low=-1;high=1;}const centered=low<=0&&high>=0,mid=centered?0:(low+high)/2,span=Math.max((centered?2*Math.max(Math.abs(low),Math.abs(high)):high-low)*1.12,1e-9);low=mid-span/2;high=mid+span/2;
 const items=rows.slice(start,start+pageSize).map(r=>{const row=source.originalRows?source.originalRows[r]:r;return {row,time:source.times[row],amplitude:source.amplitudes[r],waveform:Array.from(source.waves.subarray(r*source.n,(r+1)*source.n))};});postMessage({type:'members',id,cluster,total,page,pages,pageSize,start,order,items,low,high,full:source.full});
}
onmessage=({data:m})=>{if(m.type==='load')load(m.data).catch(e=>postMessage({type:'error',error:e.message}));else if(m.type==='members'){try{members(m);}catch(e){postMessage({type:'members',id:m.id,error:e.message});}}else if(m.type==='features'){try{if(!source?.full)throw Error('Full recorded waveforms are required for PCA');if(!pcaResult){const rows=[];for(let i=0;i<source.index.length;i++)if(source.initialLabels[source.index[i]]>0)rows.push(i);if(!rows.length)throw Error('No active recording-start members for PCA');const fit=SpikePCA.fit(source.waves,source.n,rows);pcaResult={scores:SpikePCA.project(source.waves,source.n,fit),variance:fit.variance,fit_n:fit.fit_n};}postMessage({type:'features',id:m.id,...pcaResult});}catch(e){postMessage({type:'features',id:m.id,error:e.message});}}else if(m.type==='draw')draw(m);else if(m.type==='cancel'){const job=jobs.get(m.id);if(job)job.cancel=true;jobs.delete(m.id);}};
